69\u0074\u0062\u006f\u0078\u0022\u002c\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0043\u0075\u0072\u0072\u0065\u006e\u0074\u0056\u0061\u006c\u0075\u0065\u0020\u003d\u0020\u0066\u0061\u006c\u0073\u0065\u002c\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0046\u006c\u0061\u0067\u0020\u003d\u0020\u0022\u0068\u0069\u0074\u0062\u006f\u0078\u005f\u0074\u006f\u0067\u0067\u006c\u0065\u0022\u002c\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0043\u0061\u006c\u006c\u0062\u0061\u0063\u006b\u0020\u003d\u0020\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0028\u0056\u0061\u006c\u0075\u0065\u0029\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0048\u0069\u0074\u0062\u006f\u0078\u0045\u006e\u0061\u0062\u006c\u0065\u0064\u0020\u003d\u0020\u0056\u0061\u006c\u0075\u0065\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0069\u0066\u0020\u006e\u006f\u0074\u0020\u0056\u0061\u006c\u0075\u0065\u0020\u0074\u0068\u0065\u006e\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0052\u0065\u0073\u0065\u0074\u0048\u0069\u0074\u0062\u006f\u0078\u0065\u0073\u0028\u0029\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0065\u006e\u0064\u000a\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0020\u0065\u006e\u0064\u000a\u0020\u0020\u0020\u0020\u007d\u0029\u000a\u0065\u006e\u0064\u0029\u000a\u000a\u0042\u0075\u0069\u006c\u0064\u004f\u006b\u002c\u0020\u0042\u0075\u0069\u006c\u0064\u0045\u0072\u0072\u0020\u003d\u0020\u0070\u0063\u0061\u006c\u006c\u0028\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0028\u0029\u000a\u0020\u0020\u0020\u0020\u0043\u006f\u006d\u0062\u0061\u0074\u0054\u0061\u0062\u003a\u0043\u0072\u0065\u0061\u0074\u0065\u0053\u0065\u0063\u0074\u0069\u006f\u006e\u0028\u0022\u0074\u0061\u0067\u0020\u0061\u0075\u0072\u0061\u0022\u0029\u000a\u000a\u0020\u0020\u0020\u0020\u0043\u006f\u006d\u0062\u0061\u0074\u0054\u0061\u0062\u003a